    fieldScoutingSteps:
      "ஒவ்வொரு முறையும் ஒரே பாதையில் வயலைச் சுற்றிப் பாருங்கள். ஓரப்பகுதி மற்றும் நடுப்பகுதி உட்பட பல இடங்களில் செடிகளைச் சரிபார்க்கவும். தேதி, பாதிக்கப்பட்ட பயிர்ப் பகுதி மற்றும் அறிகுறி எவ்வளவு பரவியுள்ளது என்பதைக் குறிக்கவும். முழுச் செடியையும் அருகுப் படத்தையும் எடுக்கவும். ஒரே ஒரு செடியைப் பார்த்து சிகிச்சை முடிவு செய்ய வேண்டாம்.",
