    soilSamplingSteps:
      "சுத்தமான கருவி மற்றும் பாத்திரத்தைப் பயன்படுத்தவும். வரப்பு, உரக்குவியல் மற்றும் மிக ஈரமான இடங்களைத் தவிர்க்கவும். பல இடங்களில் ஒரே ஆழத்தில் சிறு மாதிரிகளை எடுத்து கலந்து, கற்களை நீக்கி, பண்ணை மற்றும் தேதியுடன் குறியிடவும். அளவு மற்றும் பொதியிடலுக்கு ஆய்வக வழிமுறையைப் பின்பற்றவும்.",
