    waterCareSteps:
      "மேற்பரப்புக்குக் கீழுள்ள மண் ஈரம், அண்மைய மழை, பயிர் நிலை மற்றும் வடிகாலைப் பாருங்கள். தேங்கிய நீர், கசிவு மற்றும் அடைபட்ட வாய்க்கால்களைச் சரிபார்க்கவும். பயிர், மண், வானிலைக்கேற்ப நீர்த் தேவை மாறும்; எல்லா வயலுக்கும் ஒரே அட்டவணையைப் பயன்படுத்தாமல் உள்ளூர் விரிவாக்க வழிகாட்டுதலைப் பின்பற்றவும்.",
