    photoGuideSummary:
      "நிபுணர் அல்லது மாதிரி எளிதாக மதிப்பிடக்கூடிய படங்களை எடுக்கவும்.",
    photoGuideSteps:
      "கடுமையான ஒளிப்பளபளப்பு இல்லாத பகல் வெளிச்சத்தைப் பயன்படுத்தவும். இலை அல்லது பாதிக்கப்பட்ட பகுதியைத் தெளிவாக வைத்து சட்டகத்தின் பெரும்பகுதியை நிரப்பவும். முழுச் செடியின் ஒரு படமும் அருகுப் படமும் எடுக்கவும். திரைப்பிடிப்பு, அதிகமாகச் சுருக்கப்பட்ட படம் அல்லது இணையத்திலிருந்து நகலெடுத்த படத்தைப் பயன்படுத்த வேண்டாம்.",
    postHarvestTitle: "அறுவடைக்குப் பிந்தைய அடிப்படை சுகாதாரம்",
    postHarvestSummary:
      "விளைபொருளைக் கையாளும்போது தவிர்க்கக்கூடிய சேதத்தைக் குறைக்கவும்.",
